const NL = String.fromCharCode(13) + String.fromCharCode(10);
const MON = {Jan:0,Feb:1,Mar:2,Apr:3,May:4,Jun:5,Jul:6,Aug:7,Sep:8,Oct:9,Nov:10,Dec:11};
function pad(n){ return (n<10?'0':'') + n; }
function clean(s){ return String(s).replace(/<[^>]+>/g,'').replace(/&nbsp;/g,' ').replace(/&amp;/g,'&').replace(/&#0?39;|&rsquo;|&apos;/g,String.fromCharCode(39)).replace(/&quot;/g,String.fromCharCode(34)).replace(/\s+/g,' ').trim(); }
function dateParts(s){ const m = String(s).match(/([A-Z][a-z]{2})\s+(\d{1,2})[\s\S]*?(\d{4})/); if(!m) return null; const mo=MON[m[1]]; if(mo===undefined) return null; return { mo:mo, day:parseInt(m[2],10), year:parseInt(m[3],10) }; }
const today = new Date(); today.setHours(0,0,0,0);
function htmlOf(name){ try { return ($(name).first().json.data) || ''; } catch (e) { return ''; } }
const sources = [
  { base:'https://driveelectricmonth.org', html: htmlOf('Fetch DEM') },
  { base:'https://driveelectricearthmonth.org', html: htmlOf('Fetch DEEM') }
];
const events=[]; const seen=new Set();
for (const src of sources){
  const rows = src.html.split('<tr class="stat_data_row">').slice(1);
  for (const row of rows){
    const link = row.match(/event\?eventid=(\d+)"[^>]*>([\s\S]*?)<\/a>/);
    if(!link) continue;
    const id = link[1];
    const title = clean(link[2]);
    if(!title) continue;
    const cells = row.split('stat_data_cell">').slice(1).map(function(c){ return clean(c.split('</td>')[0]); });
    let dp = null; const locParts = [];
    for (const c of cells){
      if(!c) continue;
      const d = dateParts(c);
      if(d && !dp){ dp = d; continue; }
      if(c===title || c==='USA' || c.toLowerCase()==='united states') continue;
      locParts.push(c);
    }
    if(!dp) continue;
    if (new Date(dp.year,dp.mo,dp.day) < today) continue;
    const key = src.base + id;
    if (seen.has(key)) continue; seen.add(key);
    events.push({ id:id, title:title, loc:locParts.join(', '), base:src.base, year:dp.year, mo:dp.mo, day:dp.day });
  }
}
events.sort(function(a,b){ return new Date(a.year,a.mo,a.day) - new Date(b.year,b.mo,b.day); });
let ics = 'BEGIN:VCALENDAR'+NL+'VERSION:2.0'+NL+'PRODID:-//ElectrifyingTheUS//EV Events//EN'+NL+'CALSCALE:GREGORIAN'+NL;
for (const e of events){
  const dt = e.year + pad(e.mo+1) + pad(e.day);
  ics += 'BEGIN:VEVENT'+NL;
  ics += 'UID:dem-'+e.id+'@etus'+NL;
  ics += 'SUMMARY:'+e.title+NL;
  ics += 'DTSTART;VALUE=DATE:'+dt+NL;
  if(e.loc) ics += 'LOCATION:'+e.loc+NL;
  ics += 'URL:'+e.base+'/event?eventid='+e.id+NL;
  ics += 'END:VEVENT'+NL;
}
ics += 'END:VCALENDAR'+NL;
return [{ json: { ics: ics, count: events.length } }];
